/bin/bash -lc "awk '
/<Iteration_query-def>/{q="'$0; sub(/.*<Iteration_query-def>/,"",q); sub(/<.*/,"",q); hit=""; ident=""; alen=""}
/<Hit_def> && hit==""/{hit=$0; sub(/.*<Hit_def>/,"",hit); sub(/<.*/,"",hit)}
/<Hsp_identity> && ident==""/{ident=$0; sub(/.*<Hsp_identity>/,"",ident); sub(/<.*/,"",ident)}
/<Hsp_align-len> && alen==""/{alen=$0; sub(/.*<Hsp_align-len>/,"",alen); sub(/<.*/,"",alen)}
/<'"\\/Iteration>/{if(q"'!="") print q "'"\\t\" ident \"/\" alen \"\\t\" hit; q=\"\"}
' sample_even.xml > sample_even_top.tsv
wc -l sample_even_top.tsv
sed -n '1,20p' sample_even_top.tsv
printf '\\nnon-human top-hit species counts:\\n'; awk -F '\\t' '"'$3 !~ /Homo sapiens/ {print $3}'"' sample_even_top.tsv | sed -E 's/"'^PREDICTED: //'"' | sed -E 's/"'^(PREDICTED: )?([A-Z][a-z]+ [a-z]+).*/'"\\2/' | sort | uniq -c | sort -nr | head -n 30"

